  ('geo-t13','geografia','Japão: localização, fatores naturais, população e economia','treino','O que aconteceu no Japão com o início da Era Meiji, em 1868?','["O país fechou seus portos e voltou ao feudalismo", "O Japão virou colônia dos Estados Unidos", "Acabou o xogunato (feudalismo) e o país começou a se modernizar e industrializar", "O país deixou de ter imperador"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('geo-t14','geografia','Japão: localização, fatores naturais, população e economia','treino','Na Segunda Guerra Mundial, o Japão:','["Lutou ao lado dos EUA e saiu vencedor", "Ficou neutro durante toda a guerra", "Lutou ao lado da União Soviética contra a Alemanha", "Fez parte do Eixo, com Alemanha e Itália, e saiu derrotado"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('geo-t15','geografia','Japão: localização, fatores naturais, população e economia','treino','Depois da Segunda Guerra, a reconstrução da economia japonesa contou com:','["Ajuda da União Soviética e a adoção do socialismo", "Empréstimos dos Estados Unidos e a reconstrução dos conglomerados industriais", "O fechamento de todas as indústrias e a volta à agricultura", "O dinheiro de grandes reservas próprias de petróleo"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('geo-t16','geografia','Japão: localização, fatores naturais, população e economia','treino','Como se chamam os grandes conglomerados industriais japoneses de origem familiar?','["Samurais", "Xoguns", "Kibutz", "Zaibatsus"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
