  ('geo-p09','geografia','Antártida: localização e Tratado da Antártida','prova','Qual é o principal objetivo do Tratado da Antártida?','["Permitir a instalação de bases militares", "Garantir o uso pacífico e científico do continente", "Dividir as riquezas minerais entre os países", "Liberar a caça de baleias"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('geo-p10','geografia','Antártida: localização e Tratado da Antártida','prova','O que o Protocolo de Madri (1991) proibiu?','["A pesquisa científica no continente", "A visita de cientistas brasileiros", "A construção de estações de pesquisa", "A exploração de recursos minerais na Antártida por 50 anos"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
  ('geo-p11','geografia','Antártida: localização e Tratado da Antártida','prova','Sobre a Estação Antártica Comandante Ferraz, é correto afirmar:','["É argentina e fica na Terra do Fogo", "É a única estação de pesquisa do continente", "É brasileira, foi inaugurada em 1984 e fica na Ilha Rei George", "Fica exatamente no Polo Sul"]'::jsonb,'d5c2215c-797c-435b-859b-09be1fe3efbf'),
